// linked endpoints with revoke (double-gated: ask -> confirm) / approve-again.
// Routing groups + session history stay in FormLogic Desktop's Companion admin.
import { useEffect, useState } from 'preact/hooks';
import { agoLabel } from '../format';
import { POLICY_KEYS } from '../types';
import type { CompanionDevice, CompanionState } from '../types';
import { Loading } from './Loading';

interface Props {
  demo: boolean;
  companion: CompanionState | null;
  busyCompanion: string | null;
  confirmRevoke: string | null;
  busyPolicy: boolean;
  onRevokeAsk: (deviceId: string) => void;
  onRevokeCancel: () => void;
  onRevoke: (device: CompanionDevice) => void;
  onApprove: (device: CompanionDevice) => void;
  onSavePolicy: (draft: Record<string, boolean>) => void;
}

export function CompanionCard({
  demo, companion, busyCompanion, confirmRevoke, busyPolicy,
  onRevokeAsk, onRevokeCancel, onRevoke, onApprove, onSavePolicy,
}: Props) {
  // The checkbox draft mirrors the served policy until the user toggles; a
  // reload (fresh companion state) reseeds it from the server's truth.
  const [draft, setDraft] = useState<Record<string, boolean>>({});
  useEffect(() => {
    const p = companion && companion.policy ? companion.policy : {};
    const next: Record<string, boolean> = {};
    for (const [key] of POLICY_KEYS) next[key] = !!p[key];
    setDraft(next);
  }, [companion]);

  if (demo) {
    return (
      <section class="card" id="companion">
        <h2>Companion access</h2>
        <p class="faint">Not available in the shared demo.</p>
      </section>
    );
  }
  if (companion === null) {
    return (
      <section class="card" id="companion">
        <h2>Companion access</h2>
        <Loading />
      </section>
    );
  }
  if (companion.hidden) {
    return (
      <section class="card" id="companion">
        <h2>Companion access</h2>
        <p class="faint">Your role does not include Companion administration.</p>
      </section>
    );
  }

  const c = companion;
  return (
    <section class="card" id="companion">
      <h2>Companion access</h2>
      {c.policy && (
        <div>
          <p class="muted intro">Remote access policy - what linked Companion endpoints may do on live calls.</p>
          <div class="policy">
            {POLICY_KEYS.map(([key, label]) => (
              <label key={key}>
                <input
                  type="checkbox"
                  data-policy={key}
                  checked={!!draft[key]}
                  disabled={!c.canEdit}
                  onInput={(e) => setDraft({ ...draft, [key]: e.currentTarget.checked })}
                />
                {' ' + label}
              </label>
            ))}
          </div>
          {!c.policy.configured && (
            <p class="faint unset">No explicit policy is set yet - everything stays OFF until one is saved.</p>
          )}
          {c.canEdit && (
            <button type="button" class="btn" disabled={busyPolicy} onClick={() => onSavePolicy({ ...draft })}>
              {busyPolicy ? 'Saving...' : 'Save policy'}
            </button>
          )}
        </div>
      )}
      {c.devices && (
        <div>
          <p class="faint listhead">Linked endpoints</p>
          {c.devices.length === 0 ? (
            <p class="faint">No Companion endpoints are linked to this app.</p>
          ) : (
            <ul>
              {c.devices.map((d) => {
                const revoked = !!d.revokedAt;
                const seen = agoLabel(d.lastSeenAt);
                const busy = busyCompanion === d.id;
                return (
                  <li key={d.id}>
                    <div class="rowmain">
                      <span class="rowname">{d.displayName || d.id}</span>
                      {' '}
                      <span class="pill">{d.role || ''}</span>
                      {' '}
                      <span class={revoked ? 'pill bad' : 'pill ok'}>{revoked ? 'Revoked' : 'Active'}</span>
                      {seen && <div class="faint">{'Last seen ' + seen}</div>}
                    </div>
                    {revoked ? (
                      <button type="button" class="btn" disabled={busy} onClick={() => onApprove(d)}>
                        {busy ? 'Working...' : 'Approve again'}
                      </button>
                    ) : confirmRevoke === d.id ? (
                      <span>
                        <button type="button" class="btn danger-btn" disabled={busy} onClick={() => onRevoke(d)}>
                          {busy ? 'Revoking...' : 'Confirm revoke'}
                        </button>
                        {' '}
                        <button type="button" class="btn" onClick={onRevokeCancel}>Cancel</button>
                      </span>
                    ) : (
                      <button type="button" class="btn" onClick={() => onRevokeAsk(d.id)}>Revoke</button>
                    )}
                  </li>
                );
              })}
            </ul>
          )}
          <p class="faint footnote">Routing groups and the session history live in FormLogic Desktop's Companion admin.</p>
        </div>
      )}
    </section>
  );
}

/** @jsxImportSource preact */
// Recent hardware events: the newest 8 of up to 100 loaded records, each with
// its per-row timestamp (occurred_at, else submittedAt) and severity pill.
// Clear is double-gated (ask -> confirm) and never offered in the demo.
import { asRecord, whenLabel } from '../format';
import { Loading } from './Loading';

/** Rows rendered in the card; the rest stay counted in the footer line. */
const EVENTS_SHOWN = 8;

interface Props {
  demo: boolean;
  rows: FlScreenRecord[] | null;
  confirmClear: boolean;
  clearing: boolean;
  onClearAsk: () => void;
  onClearCancel: () => void;
  onClear: () => void;
}

export function EventsCard({ demo, rows, confirmClear, clearing, onClearAsk, onClearCancel, onClear }: Props) {
  let body;
  if (rows === null) {
    body = <Loading />;
  } else if (rows.length === 0) {
    body = <p class="faint">No hardware events recorded. Errors from the dongle/plugin land here automatically.</p>;
  } else {
    const shown = rows.slice(0, EVENTS_SHOWN);
    body = (
      <div>
        <ul>
          {shown.map((r) => {
            const a = asRecord(r.answers);
            const when = whenLabel(typeof a.occurred_at === 'string' && a.occurred_at !== '' ? a.occurred_at : r.submittedAt);
            const sev = String(a.severity || 'info');
            const sevClass = sev === 'error' ? 'pill bad' : sev === 'warning' ? 'pill warn' : 'pill';
            return (
              <li key={r.id}>
                <div class="rowmain">
                  <span class="rowname">{String(a.event_name || 'event')}</span>
                  {' '}
                  <span class="muted">{String(a.message || '')}</span>
                </div>
                <span class="evmeta">
                  {when && <span class="faint" title={when.full}>{when.short}</span>}
                  <span class={sevClass}>{sev}</span>
                </span>
              </li>
            );
          })}
        </ul>
        {rows.length > EVENTS_SHOWN && (
          <p class="faint shownote">{'Showing the ' + EVENTS_SHOWN + ' most recent of ' + rows.length + '.'}</p>
        )}
      </div>
    );
  }
  return (
    <section class="card" id="events">
      <div class="sectionrow">
        <h2>Recent hardware events</h2>
        {rows && rows.length > 0 && !demo && (
          confirmClear ? (
            <span>
              <button type="button" class="btn danger-btn" disabled={clearing} onClick={onClear}>
                {clearing ? 'Clearing...' : 'Confirm clear'}
              </button>
              {' '}
              <button type="button" class="btn" onClick={onClearCancel}>Cancel</button>
            </span>
          ) : (
            <button type="button" class="btn" title="Delete every recorded hardware event." onClick={onClearAsk}>Clear</button>
          )
        )}
      </div>
      {body}
    </section>
  );
}

/** @jsxImportSource preact */
// Start fresh: the whole-app record reset. Double-gated by design - the inline
// type-'delete all'-to-confirm input arms the button, and the HOST then owns
// the reset ceremony (its own confirm dialog, its own bulk clear); this screen
// only asks. 'denied' = the operator cancelled the host dialog (no noise).
import { useState } from 'preact/hooks';

interface Props {
  demo: boolean;
  busy: boolean;
  note: string;
  onStartFresh: () => void;
}

export function FreshCard({ demo, busy, note, onStartFresh }: Props) {
  const [confirm, setConfirm] = useState('');
  const armed = confirm.trim().toLowerCase() === 'delete all';
  return (
    <section class="card danger" id="fresh">
      <h2>Start fresh</h2>
      <p class="muted">
        {'Deletes '}
        <strong>every record</strong>
        {' in this app - calls, transcripts, appointments, customers, follow-up tasks, messages and hardware events - so testing starts from a clean slate. Your Receptionist Settings, forms and flows are '}
        <strong>not</strong>
        {' touched.'}
      </p>
      {demo ? (
        <p class="faint footnote">Not available in the shared demo.</p>
      ) : (
        <div class="freshrow">
          <input
            type="text"
            id="fresh-confirm"
            placeholder='Type "delete all" to enable'
            autocomplete="off"
            spellcheck={false}
            value={confirm}
            onInput={(e) => setConfirm(e.currentTarget.value)}
          />
          <button
            type="button"
            class="btn danger-btn"
            id="fresh-go"
            disabled={!armed || busy}
            onClick={() => { if (armed && !busy) onStartFresh(); }}
          >
            {busy ? 'Waiting for confirmation...' : 'Delete all records'}
          </button>
          <span class="faint" id="fresh-note">{note}</span>
        </div>
      )}
    </section>
  );
}

/* Token-only styling (--fl-* variables from the host palette) so the console
