html, body { background: transparent; }
body { margin: 0; padding: 14px 16px; color: var(--fl-text); }

#ds { max-width: 860px; margin: 0 auto; display: flex; flex-direction: column; gap: 12px; }

#ds .head { display: flex; align-items: center; justify-content: space-between; gap: 10px; }
#ds h1 { margin: 0; font-size: 17px; font-weight: 600; letter-spacing: -0.01em; }
#ds h2 {
  margin: 0 0 10px; font-size: 11px; font-weight: 700;
  text-transform: uppercase; letter-spacing: 0.08em; color: var(--fl-muted);
}

#ds .card {
  background: var(--fl-surface); border: 1px solid var(--fl-border);
  border-radius: 14px; padding: 14px 16px; box-shadow: var(--fl-shadow);
}
#ds .card.danger { border-color: var(--fl-bad); }

#ds p { margin: 0; overflow-wrap: break-word; }
#ds p + p { margin-top: 8px; }
#ds .cta { margin-top: 12px; }
#ds .intro { margin-bottom: 2px; }
#ds .unset { margin-bottom: 8px; }
#ds .listhead { margin: 14px 0 6px; }
#ds .footnote { margin-top: 10px; }
#ds .shownote { margin-top: 8px; }

#ds .btn {
  display: inline-flex; align-items: center; gap: 6px; cursor: pointer;
  font: inherit; font-size: 12px; font-weight: 500; color: var(--fl-text);
  background: var(--fl-surface); border: 1px solid var(--fl-border);
  border-radius: 10px; padding: 6px 12px;
  transition: background 0.15s ease, border-color 0.15s ease, opacity 0.15s ease;
}
#ds .btn:hover { background: var(--fl-surface-2); }
#ds .btn:focus-visible { outline: 2px solid var(--fl-accent); outline-offset: 1px; }
#ds .btn[disabled] { opacity: 0.45; cursor: not-allowed; }
#ds .btn.primary { background: var(--fl-accent); border-color: var(--fl-accent); color: var(--fl-accent-contrast); }
#ds .btn.danger-btn { background: var(--fl-bad); border-color: var(--fl-bad); color: #fff; }

#ds .muted { color: var(--fl-muted); font-size: 12.5px; }
#ds .faint { color: var(--fl-faint); font-size: 12px; }
#ds .mono { font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; font-size: 11.5px; }

/* Status chips share one height/radius/weight; the semantic variants keep the
   same footprint and add a faint currentColor tint (base surface-2 fallback
   where color-mix is unsupported). */
#ds .pill {
  display: inline-flex; align-items: center; border-radius: 999px;
  padding: 2px 9px; font-size: 10.5px; font-weight: 600; line-height: 1.5; white-space: nowrap;
  border: 1px solid var(--fl-border); color: var(--fl-muted); background: var(--fl-surface-2);
}
#ds .pill.ok { color: var(--fl-good); border-color: var(--fl-good); background: color-mix(in srgb, var(--fl-good) 8%, transparent); }
#ds .pill.warn { color: var(--fl-warn); border-color: var(--fl-warn); background: color-mix(in srgb, var(--fl-warn) 8%, transparent); }
#ds .pill.bad { color: var(--fl-bad); border-color: var(--fl-bad); background: color-mix(in srgb, var(--fl-bad) 8%, transparent); }
#ds .pill.accent { color: var(--fl-accent); border-color: var(--fl-accent); background: color-mix(in srgb, var(--fl-accent) 8%, transparent); }

#ds .banner {
  border: 1px solid var(--fl-bad); border-radius: 12px; padding: 10px 14px;
  font-size: 13px; color: var(--fl-bad);
  background: color-mix(in srgb, var(--fl-bad) 6%, transparent); overflow-wrap: break-word;
}

/* Tables and lists share one row rhythm: 9px vertical padding, hairline
