export function draftInput(key: keyof Draft, value: string): void {
  const codexModel = codexLiveCallModel(d().llm_source);
  if (key === 'model' && codexModel) {
    setDraft({ model: codexModel });
    touch();
    return;
  }
  setDraft({ [key]: value } as Partial<Draft>);
  touch();
}

export type ScreeningTextKey =
  | 'blockedNumbers'
  | 'acceptPattern'
  | 'screenMessage'
  | 'blockedMessage'
  | 'managerNumbers'
  | 'managerPin'
  | 'defaultCountryCode';

export function screeningInput(key: ScreeningTextKey, value: string): void {
  state.screening[key] = value;
  touch();
}

export type ScreeningBoolKey = 'rejectPrivate' | 'autoBlockAbuse' | 'whitelistOnly' | 'smsEnabled';

export function screeningToggle(key: ScreeningBoolKey, checked: boolean): void {
  state.screening[key] = checked;
  touch();
}

export function engineModelDirInput(value: string): void {
  state.engine.modelDir = value;
  state.engine.customDir = true;
  touch();
}

export function laneUrlInput(lane: Lane, value: string): void {
  setDraft({ [lane + '_endpoint']: value } as Partial<Draft>);
  touch();
}

export function laneChange(lane: Lane, value: string): void {
  const patch = { [lane + '_source']: value } as Partial<Draft>;
  const codexModel = lane === 'llm' ? codexLiveCallModel(value) : null;
  if (codexModel) patch.model = codexModel;
  setDraft(patch);
  enforceCodexTextOnly();
  touch();
}

export function backgroundAiChange(value: string): void {
  const patch: Partial<Draft> = { background_ai_source: value };
  // Desktop-owned Codex routes pin their own supported model. Never carry a
  // stale generic override into one of those routes.
  if (isCodexLiveCallSource(value)) patch.background_ai_model = '';
  setDraft(patch);
  touch();
}

export type WaitKey = 'autoConnectPhone' | 'holdAndCallWaiting' | 'autoHoldQueue';

export function waitChange(key: WaitKey, checked: boolean): void {
  state.waiting[key] = checked;
  if (key === 'holdAndCallWaiting' && !checked) state.waiting.autoHoldQueue = false;
  touch();
}

export function audioModeChange(v: string): void {
  state.audio.sendAudio = !isCodexLiveCallSource(d().llm_source) && (v === 'direct' || v === 'both');
  state.audio.audioTranscript = v === 'corrections' || v === 'both';
  touch();
}

export function engineChange(v: string): void {
  state.engine.engine = v;
  // The engine is a LIVE plugin setting and the voice rides the RECORD, saved
  // by a different button - so the two drift apart the moment one is saved
  // without the other. Downstream that drift is silent: the plugin now refuses
  // a voice belonging to the other engine and speaks the engine default, so a
  // stale pick here would show a voice on screen that no caller ever hears.
  // Clear it and let the new engine's default stand, which is what the picker
  // below now offers anyway.
  if (!voiceUsableByEngine(v, d().voice, state.catalog)) setDraft({ voice: '' });
  touch();
}

export function bundleChange(val: string): void {
  const sherpa = (state.catalog || []).filter((x) => x.id === 'sherpa')[0];
  const bundles = (sherpa && sherpa.bundles) || [];
  if (val === '__custom__') {
    state.engine.customDir = true;
  } else if (val === '') {
    state.engine.modelDir = '';
    state.engine.customDir = false;
    setDraft({ voice: '' });
  } else {
    const m = bundles.filter((b) => b.dir === val)[0];
    state.engine.modelDir = val;
    state.engine.customDir = false;
    setDraft({ voice: m ? m.name : baseName(val) });
  }
  touch();
}

export function unblock(num: string): void {
  const keep = splitList(state.screening.blockedNumbers).filter((x) => x !== num);
  state.screening.blockedNumbers = keep.join('\n');
  touch();
}

export function discard(): void {
  state.draft = JSON.parse(JSON.stringify(state.saved)) as Draft | null;
  enforceCodexTextOnly();
  touch();
}

export function toggleAdvanced(open: boolean): void {
  // Persists the native <details> open state across re-renders; the disclosure
  // glyph itself is CSS-driven off [open].
  state.showAdvanced = open;
  touch();
}

export function refreshRunningClick(): void {
  void refreshRunning();
}

// -- boot --

export function loadAll(): Promise<void> {
  return FormLogic.presence()
    .then((p) => {
      state.presence = p || { kind: 'none' };
    })
    .catch(() => {
      /* keep the default presence */
    })
    .then(() => Promise.all([FormLogic.can('connector.aokie.settings.get'), FormLogic.can('connector.aokie.settings.set')]))
    .then((g) => {
      state.canGet = g[0] === true;
      state.canSet = g[1] === true;
    })
    .then(() =>
      Promise.all([
        loadRecord(),
        FormLogic.aiSources()
          .then((a) => {
            state.aiSources = a as unknown as AiSource[] | null;
          })
          .catch(() => {
            state.aiSources = null;
          }),
      ]),
    )
    .then(() => FormLogic.currentUser())
    .then((u) => {
      state.demo = !!(u && u.email === 'demo@formlogic.local');
    })
    .catch(() => {
      /* demo detection is best-effort */
    })
    .then(() => {
      // mayWrite mirrors canEdit/canSubmit: the server is the real gate; the
      // sandbox has no per-form record-perm read, so allow the attempt and let
      // the API refuse. Records() succeeding implies at least view.
      state.mayWrite = true;
      applySpeechDefaults();
    })
    .then(refreshRunning)
    .then(touch);
}

// Pure helpers for the sandboxed Receptionist Settings screen - the
// behavior-preserving port of the original embedded-string screen's utility
// functions. The char-scan implementations (splitList / baseName / prettify /
// isLocale) are kept VERBATIM from the reviewed original rather than rewritten
// on regexes: they are proven against live data and the exact semantics
// (trailing-separator basename, longest-engine-prefix strip, locale shape)
// are load-bearing.

/** Loose record guard: a plain object (not an array), else {}. */
export function rec(v: unknown): Record<string, unknown> {
  return v && typeof v === 'object' && !Array.isArray(v) ? (v as Record<string, unknown>) : {};
}

/** String pass-through: non-strings become ''. */
export function str(v: unknown): string {
  return typeof v === 'string' ? v : '';
}

/** The plugin's boolean settings arrive as true or 'true'. */
export function boolish(v: unknown): boolean {
  return v === true || v === 'true';
}

/** Split a block/manager list on newline, comma or semicolon (char scan). */
export function splitList(s: string | null | undefined): string[] {
  const out: string[] = [];
  let cur = '';
  const str2 = String(s == null ? '' : s);
  for (let i = 0; i < str2.length; i++) {
    const c = str2.charAt(i);
    if (c === '\n' || c === '\r' || c === ',' || c === ';') {
      if (cur.trim()) out.push(cur.trim());
      cur = '';
    } else cur += c;
  }
  if (cur.trim()) out.push(cur.trim());
  return out;
}

/** Basename of a windows/unix path (last non-empty segment): trailing
 *  separators are ignored ('foo/bar/' resolves to 'bar', not ''). */
export function baseName(p: string | null | undefined): string {
  let s = String(p == null ? '' : p);
  while (s.length && (s.charAt(s.length - 1) === '/' || s.charAt(s.length - 1) === '\\')) s = s.slice(0, -1);
  let start = 0;
  for (let i = 0; i < s.length; i++) {
    const c = s.charAt(i);
    if (c === '\\' || c === '/') start = i + 1;
  }
  return s.slice(start);
}

const ENGINE_TOKENS: Record<string, 1> = { vits: 1, piper: 1, kokoro: 1, matcha: 1, mms: 1, coqui: 1, icefall: 1 };
const QUALITY_TOKENS: Record<string, 1> = { low: 1, medium: 1, high: 1, x_low: 1, x_high: 1 };

/** Locale token shape: 2-3 lowercase letters, optionally _ + 2 uppercase. */
function isLocale(t: string): boolean {
  const us = t.indexOf('_');
  const lang = us < 0 ? t : t.slice(0, us);
  const reg = us < 0 ? '' : t.slice(us + 1);
  if (lang.length < 2 || lang.length > 3) return false;
  for (let i = 0; i < lang.length; i++) {
    const c = lang.charAt(i);
    if (c < 'a' || c > 'z') return false;
  }
  if (us >= 0) {
    if (reg.length !== 2) return false;
    for (let j = 0; j < 2; j++) {
      const d = reg.charAt(j);
      if (d < 'A' || d > 'Z') return false;
    }
  }
  return true;
}

function titleCase(words: string[]): string {
  const joined = words.join(' ');
  const parts: string[] = [];
  let cur = '';
  for (let i = 0; i < joined.length; i++) {
    const c = joined.charAt(i);
    if (c === '_' || c === ' ') {
      if (cur) parts.push(cur);
      cur = '';
    } else cur += c;
  }
  if (cur) parts.push(cur);
  return parts.map((w) => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');
}

/** Human label for a piper/vits bundle folder name:
 *  'vits-piper-en_GB-jenny_dioco-medium' becomes 'Jenny Dioco (en_GB, medium)'. */
export function prettifyBundle(name: string): string {
  const all = String(name || '').split('-');
  const parts: string[] = [];
  for (let i = 0; i < all.length; i++) if (all[i]) parts.push(all[i]);
  let k = 0;
  while (k < parts.length && ENGINE_TOKENS[parts[k].toLowerCase()]) k++;
  const restStart = k;
  const rest = parts.slice(restStart);
  if (rest.length === 0) return name;
  const locale = isLocale(rest[0]) ? rest[0] : null;
  const last = rest[rest.length - 1];
  const quality = rest.length > 1 && QUALITY_TOKENS[last.toLowerCase()] ? last.toLowerCase() : null;
  const voiceTokens = rest.slice(locale ? 1 : 0, quality ? rest.length - 1 : rest.length);
  if (voiceTokens.length === 0) return name;
  const voice = titleCase(voiceTokens);
  const meta = [locale, quality].filter(Boolean).join(', ');
  return meta ? voice + ' (' + meta + ')' : voice;
}

// -- engine / voice pairing --
//
// MIRROR of the plugin's authority in aokie's crates/aokie-plugin/src/voice.rs
// (normalize_tts_engine + voice_matches_engine). Keep the two in lock-step: the
// plugin now REFUSES a voice belonging to the other engine and speaks the
// engine default instead, so a UI that still offers or pushes one is promising
// something the caller will never hear.

/** Port of normalize_tts_engine: fold a stored ttsEngine value to the engine
 *  that will actually speak. Unknown values are pocket - never a hard failure,
 *  because the line must speak. */
export function normalizeEngine(raw: string | null | undefined): 'pocket' | 'sherpa' {
  const v = String(raw == null ? '' : raw).trim().toLowerCase();
  return v === 'sherpa' || v === 'sherpa-onnx' || v === 'piper' ? 'sherpa' : 'pocket';
}

/**
 * Port of voice_matches_engine: does this voice belong to the engine that will
 * be asked to speak it?
 *
 * The engines name voices in different vocabularies - pocket-tts has its own
 * presets ('alba', 'eponine', ...) plus .wav clone paths, while sherpa speaks
 * through downloaded VITS/Piper/Kokoro BUNDLES ('vits-piper-en_GB-...'). Only
 * the mismatch that actually happens is refused: a BUNDLE name given to pocket.
 * Sherpa stays permissive because a bundle may name its speakers anything.
 */
export function voiceMatchesEngine(engine: string, voice: string | null | undefined): boolean {
  const v = String(voice == null ? '' : voice).trim().toLowerCase();
  if (v === '' || normalizeEngine(engine) !== 'pocket') return true;
  // A clone path is pocket's own, whatever it is called.
  if (v.endsWith('.wav') || v.endsWith('.safetensors')) return true;
  return !(
    v.startsWith('vits-')
    || v.startsWith('piper-')
    || v.startsWith('kokoro-')
    || v.indexOf('-piper-') >= 0
    || v.indexOf('-vits-') >= 0
  );
}

// -- voice catalog parse (port of parseTtsVoiceCatalog) --

export interface CatalogBundle {
  dir: string;
  name: string;
  kind: string;
}

export interface CatalogEngine {
  id: string;
  label: string;
  voices?: string[];
  bundles?: CatalogBundle[];
  scanRoot?: string;
}

export const FALLBACK_POCKET = ['', 'alba', 'cosette', 'eponine', 'fantine', 'javert', 'jean', 'marius'];

export const DEFAULT_ENGINES: CatalogEngine[] = [
  { id: 'pocket', label: 'Pocket-TTS (default)' },
  { id: 'sherpa', label: 'Sherpa - Piper/VITS voices (fast)' },
];

/** Defensive parse of settings.get's ttsVoiceCatalog side key. */
export function parseCatalog(raw: unknown): CatalogEngine[] | null {
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return null;
  const engines = (raw as { engines?: unknown }).engines;
  if (!Array.isArray(engines)) return null;
  const out: CatalogEngine[] = [];
  for (const e of engines as unknown[]) {
    if (!e || typeof e !== 'object' || Array.isArray(e)) continue;
    const er = e as Record<string, unknown>;
    if (typeof er.id !== 'string' || !er.id) continue;
    const voices = Array.isArray(er.voices)
      ? (er.voices as unknown[]).filter((v): v is string => typeof v === 'string' && v !== '')
      : undefined;
    let bundles: CatalogBundle[] | undefined;
    if (Array.isArray(er.bundles)) {
      bundles = [];
      for (const b of er.bundles as unknown[]) {
        if (!b || typeof b !== 'object' || Array.isArray(b)) continue;
        const br = b as Record<string, unknown>;
        if (typeof br.dir !== 'string' || !br.dir) continue;
        bundles.push({
          dir: br.dir,
          name: typeof br.name === 'string' && br.name ? br.name : br.dir,
          kind: typeof br.kind === 'string' && br.kind ? br.kind : 'vits',
        });
      }
    }
    const eng: CatalogEngine = { id: er.id, label: typeof er.label === 'string' && er.label ? er.label : er.id };
    if (voices) eng.voices = voices;
    if (bundles) eng.bundles = bundles;
    if (typeof er.scanRoot === 'string' && er.scanRoot) eng.scanRoot = er.scanRoot;
    out.push(eng);
  }
  return out.length ? out : null;
}

/** The pocket engine's voice list for the Voice select: '' (Default) first,
 *  then the installed voices deduped + sorted; the historic 8 as fallback. */
export function pocketVoices(cat: CatalogEngine[] | null): string[] {
  const p = (cat || []).filter((e) => e.id === 'pocket')[0];
  const vs = (p && p.voices) || [];
  if (vs.length === 0) return FALLBACK_POCKET;
  const uniq: string[] = [];
  for (let i = 0; i < vs.length; i++) if (uniq.indexOf(vs[i]) < 0) uniq.push(vs[i]);
  uniq.sort((a, b) => a.localeCompare(b));
  return [''].concat(uniq);
}

/**
 * Is this voice usable by this engine, given what is actually INSTALLED?
 *
 * Strictly better informed than voiceMatchesEngine, which is the plugin-parity
 * rule and deliberately cannot see the catalog. The plugin must stay permissive
 * for sherpa (a bundle may legitimately name a speaker 'alba', and refusing it
 * would silence a valid pick); here the catalog says whether a name is a POCKET
 * preset, so switching to sherpa with 'alba' selected is a knowable mismatch
 * rather than a guess. Used only to clear the record's voice on an explicit
 * engine change - the worst case is a reset to "Automatic", which is visible
 * and one click to undo.
 */
export function voiceUsableByEngine(engine: string, voice: string, cat: CatalogEngine[] | null): boolean {
  if (!voiceMatchesEngine(engine, voice)) return false;
  const v = String(voice == null ? '' : voice).trim();
  if (v === '' || normalizeEngine(engine) !== 'sherpa') return true;
  // index 0 is '' (Default); anything at 1+ is a pocket preset.
  return pocketVoices(cat).indexOf(v) < 1;
}

// Self-contained payload composition for the SANDBOXED Receptionist Settings
// screen. Screen sources may only import preact and sibling files, so the
// canonical modules (components/custom-screen/aokie/receptionistPayload.ts and
// data/packs/aokieReceptionistPersona.ts) CANNOT be imported here - this file
// carries copies that MUST stay behaviorally identical. The parity tests in
// aokieReceptionistSettingsScreenTsx.test.ts import BOTH sides as modules and
// pin them: DEFAULT_PERSONA / AI_GATEWAY_BASE strict-equal, composeAgentPayload
// deep-equal across the whole case matrix. Change the canonical modules first,
// then mirror the change here.
//
// ASCII-only source: the default persona's single non-ASCII character (an em
// dash) is written as the backslash-u2014 escape so the produced STRING still
// strict-equals the canonical DEFAULT_PERSONA while this source file stays
// ASCII-clean for the pack-screen gate.

/** The Receptionist Settings record fields the console edits. */
export interface Draft {
  business_name: string;
  instructions: string;
  business_info: string;
  greeting: string;
  model: string;
  llm_endpoint: string;
  stt_endpoint: string;
  tts_endpoint: string;
  llm_source: string;
  stt_source: string;
  tts_source: string;
  /** Correction lane (audioTranscript side runs): '' = the main reply model,
   *  'service:<id>' = a chat-capable Desktop service, 'custom' = the
   *  correction_endpoint URL. Composed into `audioTranscriptEndpoint`. */
  correction_source: string;
  correction_endpoint: string;
  /** Independent chat provider used only after/between calls for summaries,
   *  follow-up extraction and SMS drafting. The stored value is the desktop
   *  source id (`provider:<id>`); blank keeps the flow runner's default. */
  background_ai_source: string;
  /** Optional per-flow model override. Blank lets the provider profile choose. */
  background_ai_model: string;
  voice: string;
  reply_mode: string;
  active: string;
}

/** The lane shape composeAgentPayload resolves `service:<id>` picks against -
 *  the flow node's listing (id + loopback url while running). */
export interface SourceService {
  id: string;
  name: string;
  category: string;
